function navIcon(name) { return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${navIcons[name]}</svg>`; }
function applyTheme(){state.theme=localStorage.getItem('caremate_theme')||'light';document.documentElement.dataset.theme=state.theme;const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.content=state.theme==='dark'?'#111a18':'#f7f8f2';document.querySelectorAll('[data-theme-toggle]').forEach(button=>{const dark=state.theme==='dark';button.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');button.setAttribute('title',dark?'Switch to light theme':'Switch to dark theme');button.innerHTML=`<span aria-hidden="true">${dark?'☼':'☾'}</span><span class="theme-toggle-label">${dark?'Light':'Dark'} mode</span>`;});}
function themeToggle(){return `<button class="theme-toggle" type="button" data-action="toggle-theme" data-theme-toggle aria-label="Switch to dark theme" title="Switch to dark theme"><span aria-hidden="true">☾</span><span class="theme-toggle-label">Dark mode</span></button>`;}
function renderLanding(){document.documentElement.lang='en';root.innerHTML=`<div class="landing-page"><header class="public-header"><a class="public-brand" href="#top" aria-label="CareMate home">${logo()}</a><nav class="landing-nav" aria-label="Main navigation"><a href="#features">What you can do</a><a href="#how-it-works">How it works</a><a href="#for-care-teams">For care teams</a></nav><div class="public-actions">${themeToggle()}<button class="button button-quiet public-login" data-action="open-auth" data-mode="login">Log in</button><button class="button button-primary public-signup" data-action="open-auth" data-mode="register">Create account <span aria-hidden="true">→</span></button><button class="mobile-signup button button-primary" data-action="open-auth" data-mode="register">Get started</button></div></header><main id="top"><section class="landing-hero"><div class="hero-copy"><div class="hero-kicker"><span class="hero-kicker-dot"></span>Medication care, made clearer</div><h1>More confidence in every day of care.</h1><p class="hero-lede">Keep medicine schedules, reminders, and your care team together in one calm, easy-to-use place.</p><div class="hero-actions"><button class="button button-primary button-large" data-action="open-auth" data-mode="register">Get started <span aria-hidden="true">→</span></button><button class="button button-secondary button-large" data-action="open-auth" data-mode="login">I already have an account</button></div><div class="hero-trust"><span class="trust-check">✓</span> Your care information stays with your account</div></div><div class="hero-art" aria-label="Preview of the CareMate medication dashboard" role="img"><div class="hero-orbit orbit-one"></div><div class="hero-orbit orbit-two"></div><div class="preview-card"><div class="preview-top"><div><span class="preview-overline">YOUR CARE, AT A GLANCE</span><strong>Today’s routine</strong></div><span class="preview-date">TUE<br><b>14</b></span></div><div class="preview-progress"><div><span>Today’s doses</span><b>2 of 3</b></div><div class="progress-track"><span></span></div></div><div class="preview-dose is-done"><span class="preview-time">8:00</span><span class="preview-dose-icon">✓</span><span class="preview-dose-text"><b>Morning dose</b><small>Recorded as taken</small></span></div><div class="preview-dose is-next"><span class="preview-time">1:00</span><span class="preview-dose-icon">◷</span><span class="preview-dose-text"><b>Afternoon dose</b><small>A reminder is set</small></span></div><div class="preview-footer"><span class="preview-avatar">+</span><span>Your care team, connected</span><span class="preview-arrow">↗</span></div></div><div class="floating-note"><span class="floating-note-icon">♡</span><span><b>One place to check in</b><small>Simple, shared care</small></span></div><div class="hero-spark spark-a">✳</div><div class="hero-spark spark-b">✦</div></div></section><section class="landing-proof"><div><b>One clear routine</b><span>See medicine plans and reminders together.</span></div><div><b>Care that connects</b><span>Keep patients and caregivers on the same page.</span></div><div><b>Support when you need it</b><span>Track doses and prepare for follow-ups.</span></div></section><section class="landing-features" id="features"><div class="section-intro"><div class="eyebrow">A little more organized</div><h2>The essentials of care,<br>all in one place.</h2><p>CareMate helps make everyday care easier to follow and easier to share.</p></div><div class="feature-grid"><article class="feature-card feature-green"><span class="feature-icon">◉</span><h3>Medicine plans</h3><p>Keep medicine names, instructions, and reminder times easy to find.</p><span class="feature-index">01</span></article><article class="feature-card feature-peach"><span class="feature-icon">◷</span><h3>Gentle reminders</h3><p>Get timely nudges and record doses taken or missed.</p><span class="feature-index">02</span></article><article class="feature-card feature-lilac"><span class="feature-icon">♡</span><h3>A connected care team</h3><p>Help patients and approved caregivers stay up to date together.</p><span class="feature-index">03</span></article></div></section><section class="landing-how" id="how-it-works"><div class="how-visual"><div class="how-ring"><div class="how-center">Care<br><b>made clear</b></div><span class="how-node node-a">＋</span><span class="how-node node-b">◷</span><span class="how-node node-c">♡</span></div></div><div class="how-copy"><div class="eyebrow">Start at your own pace</div><h2>A simple place to begin.</h2><ol class="how-steps"><li><span>1</span><div><b>Create your account</b><p>Set up a patient profile or join a patient’s care team.</p></div></li><li><span>2</span><div><b>Add a care plan</b><p>Enter medicine details or review information from a prescription photo.</p></div></li><li><span>3</span><div><b>Keep everyone in the loop</b><p>Use reminders and dose records to make the routine easier to follow.</p></div></li></ol></div></section><section class="landing-cta" id="for-care-teams"><div><div class="eyebrow">For patients and caregivers</div><h2>Care works better when it feels clear.</h2><p>Bring the daily details together and make room for more peace of mind.</p></div><button class="button button-primary button-large" data-action="open-auth" data-mode="register">Create your account <span aria-hidden="true">→</span></button></section></main><footer class="landing-footer"><div>${logo()}<span>Medication support and care coordination, together.</span></div><span>CareMate supports care. For medical decisions, talk with a qualified professional.</span><button class="footer-login" data-action="open-auth" data-mode="login">Log in to CareMate →</button></footer></div>`;applyTheme();applyTranslations();}
