function tr(text){const dict=translations[state.user?.language];if(!dict)return text;return Object.entries(dict).sort((a,b)=>b[0].length-a[0].length).reduce((value,[source,target])=>value.split(source).join(target),text);}
function applyTranslations(){const lang=state.user?.language||'en';document.documentElement.lang=lang;if(!translations[lang])return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes)node.nodeValue=tr(node.nodeValue);root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>{for(const attr of ['placeholder','title','aria-label'])if(el.hasAttribute(attr))el.setAttribute(attr,tr(el.getAttribute(attr)));});}
