let pollTimer = null;

function esc(value='') { return String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function initials(name='CareMate') { return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()||'').join(''); }
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function humanDate(value, opts={month:'short',day:'numeric'}) { if(!value)return '—'; const text=String(value);const d=new Date(/^\d{4}-\d\d-\d\d$/.test(text)?`${text}T12:00:00`:text); return isNaN(d)?esc(value):d.toLocaleDateString(undefined,opts); }
function humanTime(value) { if(!value)return ''; const [h,m]=String(value).split(':').map(Number); if(Number.isNaN(h))return value; const d=new Date(); d.setHours(h,m||0,0,0); return d.toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}); }
function toast(message, error=false) { const el=document.createElement('div'); el.className=`toast${error?' error':''}`; el.textContent=tr(message); document.querySelector('#toast-region').append(el); setTimeout(()=>el.remove(),3800); }

async function api(path, options={}) {
  const headers = new Headers(options.headers || {});
  if(state.token) headers.set('Authorization', `Bearer ${state.token}`);
  if(options.body && !(options.body instanceof FormData) && !headers.has('Content-Type')) headers.set('Content-Type','application/json');
  let response;
  try { response=await fetch(path,{...options,headers}); }
  catch { throw new Error('Could not reach CareMate. Check that the backend is running.'); }
  if(response.status===401 && !path.startsWith('/api/auth/')) {
    signOut(false); throw new Error('Your session expired. Please sign in again.');
  }
  if(response.status===204) return null;
  const contentType=response.headers.get('content-type')||'';
  const data=contentType.includes('application/json')?await response.json():await response.text();
  if(!response.ok) throw new Error(data?.detail || data?.message || `Request failed (${response.status})`);
  return data;
}
const json=(method,body)=>({method,body:JSON.stringify(body)});

function showLoading() { root.innerHTML='<div class="loading-cover"><div class="loading-brand"><span class="brand-mark">+</span><span>CareMate</span><span class="spinner"></span></div></div>'; }
function logo() { return '<div class="brand"><div class="brand-mark">+</div><div><div class="brand-name">CareMate</div><div class="brand-caption">care, with a little more clarity</div></div></div>'; }

function renderAuth() {
  const login=state.authMode==='login';
  root.innerHTML=`<div class="auth-page public-auth"><header class="public-header auth-header"><a class="public-brand" href="#" data-action="back-home">${logo()}</a><div class="public-actions"><button class="button button-quiet auth-home-link" data-action="back-home">Back to home</button>${themeToggle()}</div></header><main class="auth-layout"><section class="auth-intro"><div class="auth-illustration"><span class="auth-leaf leaf-one">✳</span><span class="auth-leaf leaf-two">♡</span><div class="auth-illustration-mark">+</div><span class="auth-mini-card">Care, connected</span></div><div class="eyebrow">A calmer way to manage care</div><h1>Feel more at ease with the everyday details.</h1><p>Medicine schedules, reminders, and your care team — together in one simple space.</p><div class="auth-assurance"><span>✓</span> Private to your account</div></section><section class="auth-panel"><div class="auth-form-card"><a class="auth-mobile-brand" href="#" data-action="back-home">${logo()}</a><div class="eyebrow">Welcome to CareMate</div><h2>${login?'Welcome back':'Let’s get started'}</h2><p class="auth-lede">${login?'Sign in to pick up where you left off.':'Create an account for your care team.'}</p><div class="auth-tabs"><button class="auth-tab ${login?'active':''}" data-action="auth-mode" data-mode="login">Sign in</button><button class="auth-tab ${!login?'active':''}" data-action="auth-mode" data-mode="register">Create account</button></div>${state.authError?`<div class="missed-summary" role="alert">${esc(state.authError)}</div>`:''}<form class="auth-form" id="auth-form">${login?'':`<div class="field"><label for="auth-name">Your name</label><input class="input" id="auth-name" name="name" required maxlength="120" autocomplete="name" placeholder="Alex Morgan"></div>`}<div class="field"><label for="auth-email">Email address</label><input class="input" id="auth-email" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div>${login?'':`<div class="field"><label for="auth-role">I’m here as a</label><select class="select" id="auth-role" name="role"><option value="caretaker">Caretaker — I am the patient</option><option value="caregiver">Caregiver — I monitor patients</option></select></div>`}<div class="field"><label for="auth-password">Password</label><input class="input" id="auth-password" name="password" type="password" minlength="${login?1:10}" required autocomplete="${login?'current-password':'new-password'}" placeholder="${login?'Your password':'At least 10 characters'}"></div><button class="button button-primary auth-submit" type="submit">${login?'Sign in':'Create account'} <span aria-hidden="true">→</span></button></form><div class="auth-footer">Your account keeps care details available to you and the caregivers connected to each patient.</div><button class="auth-back-mobile" data-action="back-home">← Back to CareMate</button></div></section></main></div>`;
  applyTheme();applyTranslations();
}

function patientLabel() { return state.patient?.name || (state.patients.length?'Choose a patient':'No patient yet'); }
function shell() {
  const current=navItems.find(x=>x[0]===state.view)?.[2]||'Overview';
  const choices=state.patients.map(p=>`<option value="${p.id}" ${Number(state.patient?.id)===Number(p.id)?'selected':''}>${esc(p.name)}</option>`).join('');
  return `<div class="app-shell"><aside class="sidebar" id="sidebar">${logo()}<div class="nav-label">Workspace</div><nav class="nav-list" aria-label="Main navigation">${navItems.map(([id,icon,label])=>`<button class="nav-button ${state.view===id?'active':''}" data-action="navigate" data-view="${id}"><span class="nav-icon">${navIcon(icon)}</span>${label}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="help-card"><strong>A little help, anytime</strong><p>Medication questions can be confusing. Your care team and pharmacist are here for the details.</p><button class="button button-quiet button-small" data-action="navigate" data-view="assistant">Open care assistant →</button></div><div class="profile-row"><div class="avatar">${esc(initials(state.user?.name))}</div><div><div class="profile-name">${esc(state.user?.name)}</div><div class="profile-role">${state.user?.role==='caregiver'?'Caregiver':'Caretaker'}</div></div><button class="profile-menu" aria-label="Sign out" title="Sign out" data-action="signout">↗</button></div></div></aside><div class="main-area"><header class="topbar"><div class="top-left"><button class="icon-button mobile-menu" data-action="toggle-menu" aria-label="Open menu">☰</button><div><div class="page-kicker">${esc(current)}${state.patient?` · ${esc(state.patient.name)}`:''}</div><div class="page-title">${current==='Overview'?`Good ${greeting()}, ${esc(state.user?.name?.split(' ')[0]||'there')}`:esc(current)}</div></div></div><div class="top-actions">${state.patients.length?`<label class="sr-only" for="patient-picker">Select patient</label><select class="patient-picker" id="patient-picker">${choices}</select>`:''}<div style="position:relative"><button class="icon-button" data-action="toggle-notifications" aria-label="Notifications">♧${state.notifications.some(n=>!n.read)?'<span class="notification-dot"></span>':''}</button>${state.unreadOpen?`<div class="notification-popover" id="notification-popover">${renderNotifications(true)}</div>`:''}</div></div></header>${renderDueAlert()}<main class="content" id="view-content">${renderView()}</main></div></div>${state.modal?renderModal():''}`;
}
function renderDueAlert(){const now=new Date();const cutoff=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;const due=state.schedule.filter(x=>x.status==='pending'&&x.scheduled_date===localDate()&&x.scheduled_time<=cutoff);if(!due.length)return '';return `<section class="due-alert" role="alert"><div class="due-alert-icon">⏰</div><div class="due-alert-copy"><strong>${tr('It’s time to take your medicine')}</strong><div>${due.map(x=>`${esc(x.medicine_name)}${x.dose?` (${esc(x.dose)})`:''} · ${humanTime(x.scheduled_time)}`).join('<br>')}</div></div><button class="button button-primary button-small" data-action="navigate" data-view="overview">${tr('Review doses')}</button></section>`;}
function greeting(){const h=new Date().getHours();return h<12?'morning':h<17?'afternoon':'evening';}
function pageHeading(kicker,title,subtitle,actions=''){return `<div class="view-heading"><div><div class="eyebrow">${esc(kicker)}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function activePatientGuard(){if(state.patient)return '';return `<section class="panel empty-state"><div class="empty-illustration">♡</div><strong>Let’s add someone to your care circle</strong><p>Create a patient profile to add medicines, set reminders, and keep everyone on the same page.</p><button class="button button-primary" data-action="open-modal" data-modal="patient">Add a patient</button></section>`;}

function renderView(){
  if(!state.patient && state.view!=='care' && state.view!=='contact' && state.view!=='assistant')return `${pageHeading('Your care space','A little more organized.','Add a patient to begin managing medicines and reminders.')} ${activePatientGuard()}`;
  switch(state.view){case 'overview':return renderOverview();case 'medications':return renderMedications();case 'prescription':return renderPrescription();case 'reports':return renderReports();case 'care':return renderCare();case 'assistant':return renderAssistant();case 'contact':return renderContact();default:return renderOverview();}
}

function renderOverview(){
  const items=state.schedule;const total=items.length;const taken=items.filter(x=>x.status==='taken').length;const missed=items.filter(x=>x.status==='missed').length;const adherence=state.report?.overall_adherence_percent;
  return `${pageHeading('Your care, at a glance','A little more organized.',`Here is what is happening with ${esc(state.patient?.name||'your patient')} today.`,`<button class="button button-secondary" data-action="navigate" data-view="prescription">＋ Add prescription</button><button class="button button-primary" data-action="open-modal" data-modal="medicine">＋ Add medicine</button>`)}<section class="grid stats-grid"><article class="stat-card"><div class="stat-head">Active medicines <span class="stat-icon">◉</span></div><div class="stat-value">${state.medicines.filter(m=>m.active).length}</div><div class="stat-foot">In the current care plan</div></article><article class="stat-card"><div class="stat-head">Doses taken today <span class="stat-icon">✓</span></div><div class="stat-value">${taken}<span style="font-size:1rem;color:#9aa69d;font-weight:600"> / ${total}</span></div><div class="stat-foot">${total?`${Math.round(taken/total*100)}% of today’s schedule`:'No doses scheduled today'}</div></article><article class="stat-card"><div class="stat-head">Missed doses <span class="stat-icon">⌁</span></div><div class="stat-value">${missed}</div><div class="stat-foot">${missed?'Follow up with your care team':'You’re all caught up'}</div></article><article class="stat-card"><div class="stat-head">Adherence <span class="stat-icon">↗</span></div><div class="stat-value">${adherence==null?'—':`${adherence}%`}</div><div class="stat-foot">Over the last 30 days</div></article></section><div class="grid dashboard-grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Today’s medication plan</div><div class="panel-subtitle">A simple check-in for every dose</div></div><span class="date-chip">◷ ${humanDate(localDate(),{weekday:'short',month:'short',day:'numeric'})}</span></div>${renderSchedule(items.slice(0,8),true)}${items.length>8?`<button class="button button-quiet button-small" data-action="navigate" data-view="medications">See the full schedule →</button>`:''}</section><div class="section-stack"><section class="panel"><div class="panel-header"><div><div class="panel-title">Your last 30 days</div><div class="panel-subtitle">A gentle view of the routine</div></div><button class="button button-quiet button-small" data-action="navigate" data-view="reports">Details →</button></div><div class="adherence-ring" style="--progress:${adherence??0}%"><div class="ring-value">${adherence==null?'—':`${adherence}%`}<small>adherence</small></div></div><div class="legend"><span>On track</span><span>Still building your history</span></div></section><section class="panel"><div class="panel-header"><div><div class="panel-title">A note for today</div><div class="panel-subtitle">CareMate is here to help you keep track.</div></div><span class="stat-icon">☼</span></div><p style="font-size:.8rem;line-height:1.65;color:#748078;margin:0">A reminder is just a prompt. Always follow the prescription label, and check with a doctor or pharmacist if something doesn’t look right.</p></section></div></div>`;
}
function renderSchedule(items,actions=false){if(!items.length)return `<div class="empty-state"><div class="empty-illustration">◷</div><strong>A clear schedule for today</strong><p>Once a medicine plan is added, reminders will appear here.</p><button class="button button-secondary button-small" data-action="navigate" data-view="medications">View medicines</button></div>`;return `<div class="schedule-list">${items.map(item=>`<div class="schedule-item"><div class="schedule-time">${humanTime(item.scheduled_time)}</div><span class="schedule-dot"></span><div><div class="schedule-name">${esc(item.medicine_name)}</div><div class="schedule-meta">${esc(item.dose||'Dose not specified')}${item.timing?` · ${esc(item.timing)}`:''}</div></div>${actions&&item.status==='pending'?`<div class="dose-actions"><button class="button button-primary button-small" data-action="dose" data-id="${item.medicine_id}" data-date="${esc(item.scheduled_date)}" data-time="${esc(item.scheduled_time)}" data-status="taken">Taken</button><button class="button button-secondary button-small" data-action="dose" data-id="${item.medicine_id}" data-date="${esc(item.scheduled_date)}" data-time="${esc(item.scheduled_time)}" data-status="missed">Missed</button></div>`:`<span class="status-pill status-${esc(item.status)}">${item.status==='taken'?'Taken':item.status==='missed'?'Missed':'Pending'}</span>`}</div>`).join('')}</div>`;}

function renderMedications(){const actions=`<button class="button button-secondary" data-action="navigate" data-view="prescription">▧ Scan prescription</button><button class="button button-primary" data-action="open-modal" data-modal="medicine">＋ Add medicine</button>`;return `${pageHeading('Medication plan',`${esc(state.patient?.name)}’s medicines`,'Keep the routine easy to see. Reminder times can be changed anytime.',actions)}${state.medicines.length?`<div class="grid medicine-grid">${state.medicines.map(m=>`<article class="medicine-card"><div class="med-top"><div class="med-symbol">✳</div><div><div class="med-title">${esc(m.medicine_name)}</div><div class="med-dose">${esc(m.dose||'Dose not specified')} · ${esc(m.frequency||'Frequency not specified')}</div></div><span class="tag med-active">${m.active?'Active':'Paused'}</span></div><div class="med-details"><div><div class="detail-label">WHEN TO TAKE</div><div class="detail-value">${esc(m.timing||'Follow prescription')}</div></div><div><div class="detail-label">COURSE</div><div class="detail-value">${m.duration?`${m.duration} days`:'Ongoing'}</div></div><div><div class="detail-label">START DATE</div><div class="detail-value">${humanDate(m.start_date)}</div></div><div><div class="detail-label">REMINDERS</div><div class="med-times">${(m.reminder_times||[]).length?m.reminder_times.map(t=>`<span class="tag">${humanTime(t)}</span>`).join(''):'<span class="muted">None set</span>'}</div></div></div><div class="med-actions"><button class="button button-secondary button-small" data-action="edit-medicine" data-id="${m.id}">Edit plan</button><button class="button ${m.active?'button-danger':'button-secondary'} button-small" data-action="toggle-medicine" data-id="${m.id}" data-active="${m.active?1:0}">${m.active?'Pause medicine':'Resume'}</button></div></article>`).join('')}</div>`:`<section class="panel empty-state"><div class="empty-illustration">◉</div><strong>No medicines added yet</strong><p>Scan a prescription to start, or add a medicine plan manually. Check all details with the original prescription.</p><button class="button button-primary" data-action="navigate" data-view="prescription">Scan prescription</button></section>`}`;}

function renderPrescription(){return `${pageHeading('Prescription reader','A clearer view of the page.','Upload a prescription to extract possible medicine details. Always review the result before saving.',`<button class="button button-secondary" data-action="navigate" data-view="medications">View medication plan</button>`)}<section class="panel"><div class="panel-header"><div><div class="panel-title">Upload a prescription</div><div class="panel-subtitle">A clear, well-lit photo usually gives the best result.</div></div><span class="tag">Private to your care team</span></div><div class="upload-box" id="upload-box"><div class="upload-icon">▧</div><h3>${state.ocrFileName?esc(state.ocrFileName):'Drop a prescription image here'}</h3><p>Or choose a photo from this device. JPEG, PNG, WEBP or TIFF, up to 10 MB.</p><label class="button button-primary" for="prescription-file">Choose image</label><input class="hidden" id="prescription-file" type="file" accept="image/jpeg,image/png,image/webp,image/tiff" capture="environment"><div class="file-note">Your image is sent securely to the configured OCR service for text reading.</div></div></section>${state.ocr?renderOcrResults():''}<section class="panel" style="margin-top:17px"><div class="panel-header"><div><div class="panel-title">Before you save</div><div class="panel-subtitle">OCR can misread names, strengths, and instructions.</div></div><span class="stat-icon">!</span></div><p style="font-size:.8rem;color:#748078;line-height:1.65;margin:0">Please compare every field with the original prescription. CareMate does not prescribe or change medicines. If a detail is unclear, ask a doctor or pharmacist.</p></section>`;}
function renderOcrResults(){const meds=state.ocr.medicines||[];if(!meds.length)return `<section class="panel" style="margin-top:17px"><div class="missed-summary"><strong>No medicine details could be extracted.</strong><div class="notification-body">You can try a clearer photo or enter the plan manually. Keep the prescription nearby to check every detail.</div></div>${state.ocr.ocr_text?`<details style="margin-top:14px"><summary class="button button-quiet button-small">View extracted text</summary><pre class="ocr-text">${esc(state.ocr.ocr_text)}</pre></details>`:''}</section>`;return `<section class="panel" style="margin-top:17px"><div class="panel-header"><div><div class="panel-title">Review the extracted details</div><div class="panel-subtitle">${meds.length} possible medicine${meds.length===1?'':'s'} found. Nothing is saved until you choose.</div></div><span class="tag">Needs your review</span></div><div class="ocr-result">${meds.map((m,i)=>`<div class="ocr-med-row" data-ocr-row="${i}"><div class="field"><label>Medicine name</label><input class="input" data-ocr="medicine" value="${esc(m.medicine)}"></div><div class="field"><label>Strength / dose</label><input class="input" data-ocr="dose" value="${esc(m.dose)}"></div><div class="field"><label>Frequency</label><input class="input" data-ocr="frequency" value="${esc(m.frequency)}" placeholder="e.g. 1-0-1"></div><div class="field"><label>Duration (days)</label><input class="input" data-ocr="duration" type="number" min="0" value="${m.duration||''}"></div><div class="field"><label>Instructions / reminder times</label><input class="input" data-ocr="timing" value="${esc(m.timing)}"><input style="margin-top:5px" class="input" data-ocr="times" placeholder="08:00, 20:00" value=""></div><div class="ocr-confidence">${m.name_status==='suggested_correction'?`Name suggestion: “${esc(m.raw_medicine)}” (${Math.round((m.name_confidence||0)*100)}% match)`:`Name check: ${m.name_status==='exact_match'?'dictionary match':'please verify carefully'}`}</div><label class="review-check"><input type="checkbox" data-ocr="include" checked> Add after review</label></div>`).join('')}</div><div class="form-actions"><button class="button button-secondary" data-action="clear-ocr">Discard result</button><button class="button button-primary" data-action="save-ocr-medicines">Save reviewed medicine plans</button></div>${state.ocr.ocr_text?`<details style="margin-top:15px"><summary class="button button-quiet button-small">Show original OCR text</summary><pre class="ocr-text">${esc(state.ocr.ocr_text)}</pre></details>`:''}</section>`;}

function renderReports(){if(!state.report)return `${pageHeading('Progress report','A routine takes time.','Your medication progress will appear here.')}${activePatientGuard()}`;const r=state.report;const missed=r.missed_dose_summary||[];return `${pageHeading('Progress report',`${esc(state.patient?.name)}’s progress`,'A simple picture of doses recorded over the last 30 days.',`<button class="button button-secondary" data-action="export-report">↓ Download report</button>`)}<section class="grid stats-grid"><article class="stat-card"><div class="stat-head">Overall adherence <span class="stat-icon">↗</span></div><div class="stat-value">${r.overall_adherence_percent==null?'—':`${r.overall_adherence_percent}%`}</div><div class="stat-foot">Based on doses marked taken or missed</div></article><article class="stat-card"><div class="stat-head">Doses taken <span class="stat-icon">✓</span></div><div class="stat-value">${r.total_taken}</div><div class="stat-foot">Recorded in this period</div></article><article class="stat-card"><div class="stat-head">Doses missed <span class="stat-icon">⌁</span></div><div class="stat-value">${r.total_missed}</div><div class="stat-foot">A gentle reminder to check in</div></article><article class="stat-card"><div class="stat-head">Medicines tracked <span class="stat-icon">◉</span></div><div class="stat-value">${r.medicines.length}</div><div class="stat-foot">Across the current plan</div></article></section><div class="section-stack"><section class="panel"><div class="panel-header"><div><div class="panel-title">Medicine progress</div><div class="panel-subtitle">Days and remaining quantities are estimates.</div></div><span class="date-chip">${humanDate(r.period.start)} – ${humanDate(r.period.end)}</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Medicine</th><th>Taken</th><th>Missed</th><th>Adherence</th><th>Days left</th><th>Qty. left</th></tr></thead><tbody>${r.medicines.map(m=>`<tr><td><strong>${esc(m.medicine_name)}</strong><div class="muted" style="font-size:.7rem;margin-top:3px">${esc(m.dose||'')}</div></td><td>${m.taken}</td><td>${m.missed}</td><td>${m.adherence_percent==null?'—':`${m.adherence_percent}%`}</td><td>${m.remaining_days==null?'—':m.remaining_days}</td><td>${m.remaining_quantity==null?'—':m.remaining_quantity}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No medicine plans yet.</td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-header"><div><div class="panel-title">Missed dose check-in</div><div class="panel-subtitle">Review the medicine and scheduled time with your care team.</div></div></div>${missed.length?`<div class="missed-summary">${missed.map(m=>`<div class="missed-row"><strong>${esc(m.medicine_name)}</strong><span>${humanDate(m.scheduled_date)} · ${humanTime(m.scheduled_time)}</span></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-illustration">✓</div><strong>No missed doses recorded in this period</strong><p>Nice work keeping track of the routine.</p></div>`}</section></div>`;}

function renderCare(){const patient=state.patient;return `${pageHeading('Care team','The people who care, together.','Keep patient details and care connections in one place.',`<button class="button button-primary" data-action="open-modal" data-modal="patient">＋ Add patient</button>`)}<div class="grid two-column"><section class="panel"><div class="panel-header"><div><div class="panel-title">Your patients</div><div class="panel-subtitle">${state.patients.length} patient${state.patients.length===1?'':'s'} in your care space</div></div></div>${state.patients.length?state.patients.map(p=>`<div class="care-patient"><div class="avatar">${esc(initials(p.name))}</div><div class="care-patient-info"><div class="care-patient-name">${esc(p.name)}</div><div class="care-patient-meta">${p.date_of_birth?`Date of birth ${humanDate(p.date_of_birth,{year:'numeric',month:'short',day:'numeric'})}`:'Patient profile'}${p.phone?` · ${esc(p.phone)}`:''}</div></div><button class="button button-secondary button-small" data-action="select-patient" data-id="${p.id}">Open</button></div>`).join(''):`<div class="empty-state"><div class="empty-illustration">♡</div><strong>Your care circle starts here</strong><p>Add a patient to organize their medicines and follow-ups.</p></div>`}</section><section class="section-stack">${patient?`<div class="panel"><div class="panel-header"><div><div class="panel-title">${esc(patient.name)}</div><div class="panel-subtitle">Patient profile</div></div><span class="tag">${state.user.role==='caregiver'?'Monitoring':'Care plan'}</span></div><div class="med-details"><div><div class="detail-label">DATE OF BIRTH</div><div class="detail-value">${patient.date_of_birth?humanDate(patient.date_of_birth,{year:'numeric',month:'short',day:'numeric'}):'Not added'}</div></div><div><div class="detail-label">PHONE</div><div class="detail-value">${esc(patient.phone||'Not added')}</div></div><div><div class="detail-label">ACTIVE MEDICINES</div><div class="detail-value">${state.medicines.filter(m=>m.active).length}</div></div><div><div class="detail-label">CAREGIVERS</div><div class="detail-value">${patient.caregivers?.length||0} connected</div></div></div>${patient.notes?`<div class="detail-label">CARE NOTES</div><p style="font-size:.8rem;line-height:1.55">${esc(patient.notes)}</p>`:''}</div>`:''}<div class="panel"><div class="panel-header"><div><div class="panel-title">Care preferences</div><div class="panel-subtitle">Choose the language that feels comfortable.</div></div></div><form id="language-form" class="inline-form" style="grid-template-columns:1fr auto"><div class="field"><label for="language-select">App language preference</label><select class="select" id="language-select" name="language">${Object.entries(languageNames).map(([code,name])=>`<option value="${code}" ${state.user.language===code?'selected':''}>${name}</option>`).join('')}</select></div><button class="button button-primary">Save language</button></form><p class="muted" style="font-size:.72rem;line-height:1.5;margin-bottom:0">This saves your preference. Interface translations are still being added.</p></div>${state.user.role==='caretaker'&&patient?renderCaregiverLinkPanel():''}${patient?renderAppointmentsPanel():''}${patient?renderRemindersPanel():''}</section></div>`;}
function renderCaregiverLinkPanel(){const linked=new Set((state.patient?.caregivers||[]).map(c=>c.id));const available=state.caregivers.filter(c=>!linked.has(c.id));return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Connect a caregiver</div><div class="panel-subtitle">Give a trusted caregiver access to this patient’s plan.</div></div></div>${available.length?`<form id="link-caregiver-form" class="inline-form" style="grid-template-columns:1fr auto"><div class="field"><label for="caregiver-select">Caregiver account</label><select id="caregiver-select" name="caregiver_id" class="select">${available.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.email)}</option>`).join('')}</select></div><button class="button button-secondary">Connect</button></form>`:`<p class="muted" style="font-size:.78rem">${state.caregivers.length?'All available caregivers are already connected.':'There are no caregiver accounts yet. Ask them to create a Caregiver account first.'}</p>`}${linked.size?`<div style="margin-top:14px">${(state.patient?.caregivers||[]).map(c=>`<div class="care-patient"><div class="avatar">${esc(initials(c.name))}</div><div class="care-patient-info"><div class="care-patient-name">${esc(c.name)}</div><div class="care-patient-meta">${esc(c.email)}</div></div></div>`).join('')}</div>`:''}</section>`;}
function renderAppointmentsPanel(){return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Doctor follow-ups</div><div class="panel-subtitle">We’ll add an in-app reminder before the visit.</div></div></div><form id="appointment-form" class="form-grid"><div class="field"><label>Appointment title</label><input class="input" name="title" value="Doctor follow-up" required></div><div class="field"><label>Doctor</label><input class="input" name="doctor" placeholder="Optional"></div><div class="field"><label>Date and time</label><input class="input" type="datetime-local" name="appointment_at" required></div><div class="field"><label>Notes</label><input class="input" name="notes" placeholder="Optional"></div><div class="form-actions span-2"><button class="button button-secondary">Add follow-up</button></div></form>${state.appointments.length?`<div class="divider"></div>${state.appointments.map(a=>`<div class="care-patient"><span class="stat-icon">◷</span><div class="care-patient-info"><div class="care-patient-name">${esc(a.title)}</div><div class="care-patient-meta">${humanDate(a.appointment_at,{year:'numeric',month:'short',day:'numeric'})} · ${new Date(a.appointment_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}${a.doctor?` · ${esc(a.doctor)}`:''}</div></div><button class="button button-quiet button-small" data-action="delete-appointment" data-id="${a.id}">Remove</button></div>`).join('')}`:'<p class="muted" style="font-size:.75rem">No follow-ups scheduled yet.</p>'}</section>`;}
function renderRemindersPanel(){return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Extra reminders</div><div class="panel-subtitle">Add a personal care reminder for this patient.</div></div></div><form id="reminder-form" class="form-grid"><div class="field"><label>Reminder</label><input class="input" name="title" required placeholder="e.g. Refill prescription"></div><div class="field"><label>Date and time</label><input class="input" type="datetime-local" name="remind_at" required></div><div class="field span-2"><label>Note</label><input class="input" name="body" placeholder="Optional details"></div><div class="form-actions span-2"><button class="button button-secondary">Add reminder</button></div></form>${state.reminders.filter(r=>!r.completed).length?state.reminders.filter(r=>!r.completed).map(r=>`<div class="care-patient"><span class="stat-icon">⌁</span><div class="care-patient-info"><div class="care-patient-name">${esc(r.title)}</div><div class="care-patient-meta">${new Date(r.remind_at).toLocaleString()}</div></div><button class="button button-quiet button-small" data-action="delete-reminder" data-id="${r.id}">Remove</button></div>`).join(''):'<p class="muted" style="font-size:.75rem">No extra reminders added.</p>'}</section>`;}

function activePatientGuard(){const caregiver=state.user?.role==='caregiver';return `<section class="panel empty-state"><div class="empty-illustration">♡</div><strong>${caregiver?'Connect with a patient':'Your patient profile is ready'}</strong><p>${caregiver?'Request access using the email address the patient used to register. They can approve your connection from their CareMate account.':'Your profile is also the patient record. You can add medicines and care details here.'}</p>${caregiver?'<button class="button button-primary" data-action="open-modal" data-modal="request-access">Request patient access</button>':'<button class="button button-primary" data-action="navigate" data-view="care">View your profile</button>'}</section>`;}

function renderCareRequests(){const rows=state.caregiverRequests||[];if(state.user.role==='caretaker'){const pending=rows.filter(r=>r.status==='pending');return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Caregiver access</div><div class="panel-subtitle">Review requests to join your care team.</div></div></div>${pending.length?pending.map(r=>`<div class="care-patient"><div class="avatar">${esc(initials(r.caregiver_name))}</div><div class="care-patient-info"><div class="care-patient-name">${esc(r.caregiver_name)}</div><div class="care-patient-meta">${esc(r.caregiver_email)} · requested ${humanDate(r.created_at)}</div></div><button class="button button-primary button-small" data-action="caregiver-decision" data-id="${r.id}" data-status="accepted">Approve</button><button class="button button-secondary button-small" data-action="caregiver-decision" data-id="${r.id}" data-status="declined">Decline</button></div>`).join(''):'<p class="muted" style="font-size:.78rem">No caregiver requests are waiting for approval.</p>'}</section>`;}return `<section class="panel"><div class="panel-header"><div><div class="panel-title">Access requests</div><div class="panel-subtitle">Patient connections you have requested.</div></div><button class="button button-secondary button-small" data-action="open-modal" data-modal="request-access">＋ Request access</button></div>${rows.length?rows.map(r=>`<div class="care-patient"><span class="avatar">♡</span><div class="care-patient-info"><div class="care-patient-name">${esc(r.patient_name)}</div><div class="care-patient-meta">${esc(r.caretaker_email)} · ${humanDate(r.created_at)}</div></div><span class="status-pill ${r.status==='accepted'?'status-taken':r.status==='declined'?'status-missed':'status-pending'}">${esc(r.status)}</span></div>`).join(''):'<p class="muted" style="font-size:.78rem">Request access to a patient using their caretaker account email.</p>'}</section>`;}

function renderCare(){const patient=state.patient;const caregiver=state.user.role==='caregiver';return `${pageHeading('Care team',caregiver?'Patients in your care':'Your patient profile',caregiver?'View the patients who have connected you to their care team.':'You are the patient on this account. Caregivers can request access to monitor your care.',caregiver?`<button class="button button-primary" data-action="open-modal" data-modal="request-access">＋ Request access</button>`:'')}<div class="grid two-column"><section class="panel"><div class="panel-header"><div><div class="panel-title">${caregiver?'Connected patients':'Your profile'}</div><div class="panel-subtitle">${caregiver?`${state.patients.length} patient${state.patients.length===1?'':'s'} connected`:esc(state.user.name)}</div></div>${!caregiver&&patient?'<button class="button button-secondary button-small" data-action="open-modal" data-modal="patient-profile">Edit profile</button>':''}</div>${caregiver?(state.patients.length?state.patients.map(p=>`<div class="care-patient"><div class="avatar">${esc(initials(p.name))}</div><div class="care-patient-info"><div class="care-patient-name">${esc(p.name)}</div><div class="care-patient-meta">${p.date_of_birth?`Date of birth ${humanDate(p.date_of_birth,{year:'numeric',month:'short',day:'numeric'})}`:'Patient profile'}${p.phone?` · ${esc(p.phone)}`:''}</div></div><button class="button button-secondary button-small" data-action="select-patient" data-id="${p.id}">Open</button></div>`).join(''):'<div class="empty-state"><div class="empty-illustration">♡</div><strong>No patient connections yet</strong><p>Request access with the email address a patient uses for CareMate.</p></div>'):(patient?`<div class="med-details"><div><div class="detail-label">DATE OF BIRTH</div><div class="detail-value">${patient.date_of_birth?humanDate(patient.date_of_birth,{year:'numeric',month:'short',day:'numeric'}):'Not added'}</div></div><div><div class="detail-label">PHONE</div><div class="detail-value">${esc(patient.phone||'Not added')}</div></div><div><div class="detail-label">ACTIVE MEDICINES</div><div class="detail-value">${state.medicines.filter(m=>m.active).length}</div></div><div><div class="detail-label">CONNECTED CAREGIVERS</div><div class="detail-value">${patient.caregivers?.length||0}</div></div></div>${patient.notes?`<div class="detail-label">CARE NOTES</div><p style="font-size:.8rem;line-height:1.55">${esc(patient.notes)}</p>`:''}`:'<p class="muted">Your patient profile will appear here.</p>')}</section><section class="section-stack">${renderCareRequests()}<div class="panel"><div class="panel-header"><div><div class="panel-title">Language preference</div><div class="panel-subtitle">Choose the language that feels comfortable.</div></div></div><form id="language-form" class="inline-form" style="grid-template-columns:1fr auto"><div class="field"><label for="language-select">App language</label><select class="select" id="language-select" name="language">${Object.entries(languageNames).map(([code,name])=>`<option value="${code}" ${state.user.language===code?'selected':''}>${name}</option>`).join('')}</select></div><button class="button button-primary">Save language</button></form><p class="muted" style="font-size:.72rem;line-height:1.5;margin-bottom:0">Your preference is stored. Translated interface text is still being added.</p></div>${patient?renderAppointmentsPanel():''}${patient?renderRemindersPanel():''}</section></div>`;}

const assistantUi={
  en:{title:'Care assistant',subtitle:'A little support, when you need it.',description:'Ask about using CareMate. For medicine decisions, contact a doctor or pharmacist.',welcome:'Hi! I can help you use CareMate and keep track of care tasks. I cannot diagnose, recommend doses, or change a prescription. What would you like help with?',question:'Your question',placeholder:'Type a question…',send:'Send',emergency:'If you may be facing an emergency, contact your local emergency service now.',thinking:'One moment…'},
  hi:{title:'देखभाल सहायक',subtitle:'ज़रूरत पड़ने पर थोड़ी मदद।',description:'CareMate के उपयोग के बारे में पूछें। दवा संबंधी फैसलों के लिए डॉक्टर या फार्मासिस्ट से संपर्क करें।',welcome:'नमस्ते! मैं CareMate का उपयोग करने और देखभाल के कामों का रिकॉर्ड रखने में मदद कर सकता हूँ। मैं बीमारी का निदान, खुराक की सलाह या पर्चे में बदलाव नहीं कर सकता। आपको किस बारे में मदद चाहिए?',question:'आपका सवाल',placeholder:'अपना सवाल लिखें…',send:'भेजें',emergency:'आपातकाल की आशंका हो तो अभी स्थानीय आपातकालीन सेवा से संपर्क करें।',thinking:'एक क्षण…'},
  mr:{title:'काळजी सहाय्यक',subtitle:'गरज असेल तेव्हा थोडी मदत.',description:'CareMate वापरण्याबद्दल विचारा. औषधांबाबत डॉक्टर किंवा फार्मासिस्टशी संपर्क साधा.',welcome:'नमस्कार! CareMate वापरणे आणि काळजीच्या कामांची नोंद ठेवणे यासाठी मी मदत करू शकतो. मी निदान, मात्रेचा सल्ला किंवा प्रिस्क्रिप्शनमध्ये बदल करू शकत नाही. तुम्हाला कशासाठी मदत हवी आहे?',question:'तुमचा प्रश्न',placeholder:'प्रश्न लिहा…',send:'पाठवा',emergency:'आपत्कालीन परिस्थितीची शक्यता असल्यास स्थानिक आपत्कालीन सेवेशी आत्ताच संपर्क साधा.',thinking:'एक क्षण…'},
};
assistantUi.en.description='Ask about your saved medicines, today’s schedule, missed doses, or how to use CareMate. For treatment advice, contact a doctor or pharmacist.';
assistantUi.en.welcome='Hi! I can look up medicine plans and dose records saved in CareMate, and explain how to use the app. Ask things like “What medicines are saved?” or “What is scheduled today?” I can’t diagnose or recommend treatment.';
assistantUi.hi.description='अपनी दवा योजनाओं, आज की खुराकों, छूटी खुराकों या CareMate के उपयोग के बारे में पूछें। इलाज की सलाह के लिए डॉक्टर या फार्मासिस्ट से संपर्क करें।';
assistantUi.hi.welcome='नमस्ते! मैं CareMate में सहेजी गई दवा योजनाएँ और खुराक का रिकॉर्ड ढूँढ़ सकता हूँ और ऐप का उपयोग समझा सकता हूँ। पूछें: “कौन-सी दवाएँ दर्ज हैं?” या “आज क्या तय है?” मैं बीमारी का निदान या इलाज की सलाह नहीं दे सकता।';
assistantUi.mr.description='जतन केलेली औषध योजना, आजचे वेळापत्रक, चुकलेल्या मात्रा किंवा CareMate वापरण्याबद्दल विचारा. उपचाराच्या सल्ल्यासाठी डॉक्टर किंवा फार्मासिस्टशी संपर्क साधा.';
assistantUi.mr.welcome='नमस्कार! CareMate मध्ये जतन केलेली औषध योजना आणि मात्रांची नोंद मी शोधू शकतो, तसेच अॅप वापरण्याबद्दल सांगू शकतो. “कोणती औषधे नोंदली आहेत?” किंवा “आजचे वेळापत्रक काय आहे?” असे विचारा. मी निदान किंवा उपचारांचा सल्ला देऊ शकत नाही.';
function renderAssistant(){const copy=assistantUi[state.user?.language]||assistantUi.en;const history=state.chatMessages.map(item=>`<div class="chat-bubble ${item.role==='user'?'chat-user':'chat-bot'}">${esc(item.message)}</div>`).join('');return `${pageHeading(copy.title,copy.subtitle,copy.description)}<section class="panel" style="max-width:760px"><div class="chat-window" id="chat-window"><div class="chat-bubble chat-bot">${esc(copy.welcome)}</div>${history}</div><form class="chat-form" id="chat-form"><label class="sr-only" for="chat-message">${esc(copy.question)}</label><input class="input" id="chat-message" name="message" required maxlength="2000" placeholder="${esc(copy.placeholder)}"><button class="button button-primary">${esc(copy.send)}</button></form><p class="muted" style="font-size:.7rem;line-height:1.5">${esc(copy.emergency)}</p></section>`;}
function renderContact(){return `${pageHeading('We’re here to help','Get in touch.','Send a note to the CareMate team.')}<section class="panel" style="max-width:670px"><form id="contact-form" class="form-grid"><div class="field"><label for="contact-name">Your name</label><input id="contact-name" name="name" class="input" required maxlength="120" value="${esc(state.user.name)}"></div><div class="field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" class="input" required value="${esc(state.user.email)}"></div><div class="field span-2"><label for="contact-message">How can we help?</label><textarea id="contact-message" name="message" class="textarea" required maxlength="5000" placeholder="Write your message here…"></textarea></div><div class="form-actions span-2"><button class="button button-primary">Send message</button></div></form></section>`;}

function renderNotifications(popover=false){
  const permission=('Notification' in window)?Notification.permission:'unsupported';
  if(!state.notifications.length)return `<div class="empty-state" style="padding:22px 8px"><strong>You're all caught up</strong><p>New reminders will appear here.</p></div>${popover&&permission==='default'?'<button class="button button-secondary button-small" data-action="enable-browser-alerts">Enable desktop alerts</button>':''}`;
  return `<div class="notification-list">${state.notifications.slice(0,popover?5:30).map(n=>`<article class="notification-item ${n.read?'':'unread'}"><span class="notification-bead"></span><div><div class="notification-title">${esc(n.title)}</div><div class="notification-body">${esc(n.body)}</div><button class="button button-quiet button-small" data-action="read-notification" data-id="${n.id}">Mark read</button>${n.kind==='medicine'?`<button class="button button-quiet button-small" data-action="read-aloud" data-text="${esc(`${n.title}. ${n.body}`)}">Read aloud</button>`:''}</div><div class="notification-time">${n.read?'':'New'}</div></article>`).join('')}</div>${popover&&permission==='default'?'<button class="button button-secondary button-small" data-action="enable-browser-alerts">Enable desktop alerts</button>':''}${popover?'<button class="button button-quiet button-small" data-action="navigate" data-view="overview">Close</button>':''}`;
}

function renderModal(){const modal=state.modal;if(modal==='patient')return `<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Care team</div><div class="modal-title">Add a patient</div></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="patient-form" class="form-grid"><div class="field span-2"><label for="patient-name">Patient name</label><input id="patient-name" class="input" name="name" required maxlength="120" placeholder="Full name"></div><div class="field"><label for="patient-dob">Date of birth</label><input id="patient-dob" class="input" name="date_of_birth" type="date"></div><div class="field"><label for="patient-phone">Phone</label><input id="patient-phone" class="input" name="phone" type="tel" placeholder="Optional"></div><div class="field span-2"><label for="patient-notes">Care notes</label><textarea id="patient-notes" name="notes" class="textarea" placeholder="Optional notes for the care team"></textarea></div><div class="form-actions span-2"><button class="button button-secondary" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Create patient</button></div></form></section></div>`;
  if(modal==='medicine')return `<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Medication plan</div><div class="modal-title">Add a medicine</div></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="medicine-form" class="form-grid"><div class="field span-2"><label for="med-name">Medicine name</label><input id="med-name" name="medicine_name" class="input" required placeholder="Use the name from the prescription"></div><div class="field"><label for="med-dose">Strength / dose</label><input id="med-dose" name="dose" class="input" placeholder="e.g. 500 mg"></div><div class="field"><label for="med-frequency">Frequency</label><input id="med-frequency" name="frequency" class="input" placeholder="e.g. 1-0-1"></div><div class="field"><label for="med-duration">Duration (days)</label><input id="med-duration" name="duration" type="number" min="0" class="input" placeholder="0 for ongoing"></div><div class="field"><label for="med-quantity">Quantity on hand</label><input id="med-quantity" name="quantity" type="number" min="0" step="any" class="input" placeholder="Optional"></div><div class="field span-2"><label for="med-timing">Prescription instructions</label><input id="med-timing" name="timing" class="input" placeholder="e.g. after food"></div><div class="field"><label for="med-start">Start date</label><input id="med-start" name="start_date" type="date" class="input" value="${localDate()}" required></div><div class="field"><label for="med-times">Reminder times</label><input id="med-times" name="reminder_times" class="input" placeholder="08:00, 20:00"></div><div class="form-actions span-2"><button class="button button-secondary" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Save medicine</button></div></form><p class="muted" style="font-size:.7rem;line-height:1.5;margin-bottom:0">Suggested reminder times are defaults. Confirm them against the prescription.</p></section></div>`;
  if(modal==='edit-medicine'){const m=state.medicines.find(x=>x.id===Number(state.editId));if(!m)return '';return `<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Medication plan</div><div class="modal-title">Edit ${esc(m.medicine_name)}</div></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="edit-medicine-form" data-id="${m.id}" class="form-grid"><div class="field span-2"><label>Medicine name</label><input class="input" name="medicine_name" required value="${esc(m.medicine_name)}"></div><div class="field"><label>Dose</label><input class="input" name="dose" value="${esc(m.dose)}"></div><div class="field"><label>Frequency</label><input class="input" name="frequency" value="${esc(m.frequency)}"></div><div class="field"><label>Duration (days)</label><input class="input" name="duration" type="number" min="0" value="${m.duration}"></div><div class="field"><label>Quantity</label><input class="input" name="quantity" type="number" min="0" step="any" value="${m.quantity??''}"></div><div class="field span-2"><label>Instructions</label><input class="input" name="timing" value="${esc(m.timing)}"></div><div class="field"><label>Start date</label><input class="input" name="start_date" type="date" value="${esc(m.start_date)}"></div><div class="field"><label>Reminder times</label><input class="input" name="reminder_times" value="${esc((m.reminder_times||[]).join(', '))}"></div><div class="form-actions span-2"><button class="button button-secondary" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Save changes</button></div></form></section></div>`;}
  return '';
}

const renderExistingModal=renderModal;
renderModal=function(){
  if(state.modal==='request-access')return `<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Connect to a patient</div><div class="modal-title">Request care access</div></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><p class="muted" style="font-size:.82rem;line-height:1.6">Enter the email the patient used for their Caretaker account. They approve your request before you can see their care information.</p><form id="request-access-form" class="form-grid"><div class="field span-2"><label for="caretaker-email">Patient account email</label><input id="caretaker-email" class="input" type="email" name="caretaker_email" required placeholder="patient@example.com"></div><div class="form-actions span-2"><button class="button button-secondary" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Send request</button></div></form></section></div>`;
  if(state.modal==='patient-profile'&&state.patient)return `<div class="modal-backdrop" data-action="backdrop"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Your patient record</div><div class="modal-title">Update your profile</div></div><button class="modal-close" data-action="close-modal" aria-label="Close">×</button></div><form id="patient-profile-form" class="form-grid"><div class="field span-2"><label>Your name</label><input class="input" name="name" required value="${esc(state.patient.name)}"></div><div class="field"><label>Date of birth</label><input class="input" name="date_of_birth" type="date" value="${esc(state.patient.date_of_birth||'')}"></div><div class="field"><label>Phone</label><input class="input" name="phone" value="${esc(state.patient.phone||'')}"></div><div class="field span-2"><label>Care notes</label><textarea class="textarea" name="notes">${esc(state.patient.notes||'')}</textarea></div><div class="form-actions span-2"><button class="button button-secondary" type="button" data-action="close-modal">Cancel</button><button class="button button-primary">Save profile</button></div></form></section></div>`;
  return renderExistingModal();
};
function render(){applyTheme();if(!state.token){state.publicPage==='auth'?renderAuth():renderLanding();return;}root.innerHTML=shell();root.querySelector('.top-actions')?.insertAdjacentHTML('afterbegin',themeToggle());applyTranslations();applyTheme();const chatWindow=root.querySelector('#chat-window');if(chatWindow)chatWindow.scrollTop=chatWindow.scrollHeight;}
function setView(view){state.view=view;state.unreadOpen=false;document.querySelector('#sidebar')?.classList.remove('open');render();}
function signOut(show=true){if(state.token)api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.token=null;state.user=null;state.patient=null;state.patients=[];state.chatMessages=[];state.publicPage='landing';localStorage.removeItem('caremate_token');if(show)toast('You have signed out.');renderLanding();}

async function loadWorkspace(){
  state.loading=true;
  try{
    state.user=await api('/api/auth/me');
    state.patients=await api('/api/patients');
    state.caregivers=[];
    state.caregiverRequests=await api('/api/caregiver-requests');
    const remembered=Number(sessionStorage.getItem('caremate_patient'));
    state.patient=state.patients.find(p=>p.id===remembered)||state.patients[0]||null;
    if(state.patient)sessionStorage.setItem('caremate_patient',state.patient.id);
    await loadPatientData();
    state.notifications=await api('/api/notifications?unread_only=true');
    state.chatMessages=await api('/api/chat/history');
    state.seenNotificationIds=new Set(state.notifications.map(n=>n.id));
  }catch(error){if(state.token)toast(error.message,true);if(!state.user){state.token=null;localStorage.removeItem('caremate_token');}}
  state.loading=false;render();
}
async function loadPatientData(){
  if(!state.patient){state.schedule=[];state.medicines=[];state.report=null;state.appointments=[];state.reminders=[];state.prescriptions=[];return;}
  const id=state.patient.id;
  const requests=[api(`/api/patients/${id}/schedule`),api(`/api/patients/${id}/medicines`),api(`/api/patients/${id}/reports/adherence`),api(`/api/patients/${id}/appointments`),api(`/api/patients/${id}/reminders`),api(`/api/patients/${id}/prescriptions`),api(`/api/patients/${id}`)];
  const result=await Promise.allSettled(requests);
  const keys=['schedule','medicines','report','appointments','reminders','prescriptions','patient'];
  result.forEach((r,i)=>{if(r.status==='fulfilled')state[keys[i]]=r.value;else if(r.reason?.message!=='Your session expired. Please sign in again.')console.warn(keys[i],r.reason);});
}
async function refresh(){try{state.patients=await api('/api/patients');state.caregiverRequests=await api('/api/caregiver-requests');if(state.patient&&!state.patients.some(p=>p.id===state.patient.id))state.patient=null;if(state.patient)state.patient=state.patients.find(p=>p.id===state.patient.id)||state.patient;await loadPatientData();state.notifications=await api('/api/notifications?unread_only=true');render();}catch(e){toast(e.message,true);}}

async function pollNotifications(){const items=await api('/api/notifications?unread_only=true');const fresh=items.filter(n=>!state.seenNotificationIds.has(n.id));state.notifications=items;state.caregiverRequests=await api('/api/caregiver-requests');for(const item of fresh){state.seenNotificationIds.add(item.id);toast(`${item.title}: ${item.body}`);if('Notification'in window&&Notification.permission==='granted'){const notice=new Notification(tr(item.title),{body:tr(item.body),tag:`caremate-${item.id}`});notice.onclick=()=>window.focus();}}}

async function uploadPrescription(file){if(!file)return;if(file.size>10*1024*1024){toast('Choose an image under 10 MB.',true);return;}if(!state.patient){toast('Add or choose a patient first.',true);return;}const box=document.querySelector('#upload-box');if(box)box.innerHTML='<div class="spinner" style="margin:auto"></div><p>Reading the image… this can take a moment.</p>';try{const data=await api(`/api/patients/${state.patient.id}/prescriptions/ocr`,{method:'POST',body:(()=>{const f=new FormData();f.append('image',file);return f;})()});state.ocr=data;state.ocrFileName=file.name;render();toast('Text extracted. Please review every detail.');}catch(e){toast(e.message,true);render();}}

async function saveOcrMedicines(){if(!state.ocr||!state.patient)return;const rows=[...document.querySelectorAll('[data-ocr-row]')];let saved=0;for(const row of rows){if(!row.querySelector('[data-ocr="include"]').checked)continue;const value=key=>row.querySelector(`[data-ocr="${key}"]`)?.value.trim()||'';const times=value('times').split(',').map(t=>t.trim()).filter(Boolean);const payload={medicine_name:value('medicine'),dose:value('dose'),frequency:value('frequency'),timing:value('timing'),duration:Number(value('duration')||0),start_date:localDate(),reminder_times:times};if(!payload.medicine_name){toast('Each medicine needs a name.',true);return;}try{await api(`/api/patients/${state.patient.id}/medicines?prescription_id=${state.ocr.prescription_id}`,json('POST',payload));saved++;}catch(e){toast(e.message,true);return;}}if(!saved){toast('Choose at least one reviewed medicine.',true);return;}state.ocr=null;state.ocrFileName='';await refresh();setView('medications');toast(`${saved} reviewed medicine plan${saved===1?'':'s'} saved.`);}

function formData(form){return Object.fromEntries(new FormData(form).entries());}
async function submitAuth(form){const values=formData(form);state.authError='';try{const data=state.authMode==='login'?await api('/api/auth/login',json('POST',values)):await api('/api/auth/register',json('POST',{...values,language:'en'}));state.token=data.access_token;state.user=data.user;localStorage.setItem('caremate_token',state.token);await loadWorkspace();startPolling();}catch(e){state.authError=e.message;renderAuth();}}
function renderChatMessage(text,kind){const win=document.querySelector('#chat-window');if(!win)return;const b=document.createElement('div');b.className=`chat-bubble ${kind==='user'?'chat-user':'chat-bot'}`;b.textContent=text;win.append(b);win.scrollTop=win.scrollHeight;}

root.addEventListener('click',async event=>{
  const actionEl=event.target.closest('[data-action]');if(!actionEl)return;const action=actionEl.dataset.action;
  try{
    if(action==='open-auth'){state.authMode=actionEl.dataset.mode;state.authError='';state.publicPage='auth';renderAuth();}
    if(action==='back-home'){state.publicPage='landing';state.authError='';renderLanding();}
    if(action==='toggle-theme'){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('caremate_theme',state.theme);applyTheme();}
    if(action==='auth-mode'){state.authMode=actionEl.dataset.mode;state.authError='';renderAuth();}
    if(action==='navigate')setView(actionEl.dataset.view);
    if(action==='toggle-menu')document.querySelector('#sidebar')?.classList.toggle('open');
    if(action==='toggle-notifications'){state.unreadOpen=!state.unreadOpen;render();}
    if(action==='enable-browser-alerts'){if(!('Notification'in window)){toast('This browser does not support desktop notifications.',true);}else{const permission=await Notification.requestPermission();toast(permission==='granted'?'Desktop alerts are enabled while CareMate is open.':'Desktop alerts were not enabled.',permission!=='granted');render();}}
    if(action==='caregiver-decision'){await api(`/api/caregiver-requests/${actionEl.dataset.id}`,json('PATCH',{status:actionEl.dataset.status}));await refresh();toast(`Caregiver request ${actionEl.dataset.status}.`);}
    if(action==='signout')signOut();
    if(action==='open-modal'){state.modal=actionEl.dataset.modal;render();}
    if(action==='close-modal'){state.modal=null;render();}
    if(action==='backdrop'&&event.target===actionEl){state.modal=null;render();}
    if(action==='select-patient'){state.patient=state.patients.find(p=>p.id===Number(actionEl.dataset.id))||null;sessionStorage.setItem('caremate_patient',state.patient?.id||'');await loadPatientData();render();}
    if(action==='dose'){actionEl.disabled=true;try{await api(`/api/medicines/${actionEl.dataset.id}/doses`,json('POST',{scheduled_date:actionEl.dataset.date,scheduled_time:actionEl.dataset.time,status:actionEl.dataset.status}));await refresh();toast(actionEl.dataset.status==='taken'?'Dose recorded.':'Missed dose recorded for the care team.');}catch(e){actionEl.disabled=false;toast(`Could not record this dose: ${e.message}`,true);}}
    if(action==='read-notification'){await api(`/api/notifications/${actionEl.dataset.id}/read`,json('PATCH',{}));state.notifications=state.notifications.filter(n=>n.id!==Number(actionEl.dataset.id));render();}
    if(action==='delete-appointment'){if(!confirm('Remove this follow-up?'))return;await api(`/api/appointments/${actionEl.dataset.id}`,{method:'DELETE'});await refresh();toast('Follow-up removed.');}
    if(action==='delete-reminder'){if(!confirm('Remove this reminder?'))return;await api(`/api/reminders/${actionEl.dataset.id}`,{method:'DELETE'});await refresh();toast('Reminder removed.');}
    if(action==='save-ocr-medicines')await saveOcrMedicines();
    if(action==='clear-ocr'){state.ocr=null;state.ocrFileName='';render();}
    if(action==='toggle-medicine'){const active=actionEl.dataset.active==='1';await api(`/api/medicines/${actionEl.dataset.id}`,json('PATCH',{active:active?0:1}));await refresh();toast(active?'Medicine paused.':'Medicine resumed.');}
    if(action==='edit-medicine'){state.modal='edit-medicine';state.editId=actionEl.dataset.id;render();}
    if(action==='read-aloud'){const text=actionEl.dataset.text;if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text));}else toast('Speech playback is not available in this browser.',true);}
    if(action==='export-report')exportReport();
  }catch(e){toast(e.message,true);}
});

root.addEventListener('change',async event=>{
  if(event.target.id==='language-select'){event.target.form?.requestSubmit();return;}
  if(event.target.id==='patient-picker'){state.patient=state.patients.find(p=>p.id===Number(event.target.value))||null;sessionStorage.setItem('caremate_patient',state.patient?.id||'');await loadPatientData();render();return;}
  if(event.target.id==='prescription-file'){await uploadPrescription(event.target.files?.[0]);return;}
});
root.addEventListener('dragover',event=>{if(event.target.closest('#upload-box')){event.preventDefault();event.target.closest('#upload-box').classList.add('drag');}});
root.addEventListener('dragleave',event=>event.target.closest('#upload-box')?.classList.remove('drag'));
root.addEventListener('drop',async event=>{const box=event.target.closest('#upload-box');if(box){event.preventDefault();box.classList.remove('drag');await uploadPrescription(event.dataTransfer.files?.[0]);}});

root.addEventListener('submit',async event=>{
  const form=event.target;event.preventDefault();
  try{
    if(form.id==='auth-form'){await submitAuth(form);return;}
    if(form.id==='patient-form'){const v=formData(form);if(!v.date_of_birth)delete v.date_of_birth;if(!v.phone)delete v.phone;if(!v.notes)delete v.notes;const p=await api('/api/patients',json('POST',v));state.modal=null;await refresh();state.patient=state.patients.find(x=>x.id===p.id)||p;await loadPatientData();setView('overview');toast('Patient profile created.');return;}
    if(form.id==='medicine-form'){const v=formData(form);v.duration=Number(v.duration||0);v.quantity=v.quantity===''?null:Number(v.quantity);v.reminder_times=v.reminder_times.split(',').map(t=>t.trim()).filter(Boolean);if(v.quantity===null)delete v.quantity;await api(`/api/patients/${state.patient.id}/medicines`,json('POST',v));state.modal=null;await refresh();toast('Medicine plan saved. Please confirm its schedule.');return;}
    if(form.id==='edit-medicine-form'){const v=formData(form);v.duration=Number(v.duration||0);v.quantity=v.quantity===''?null:Number(v.quantity);v.reminder_times=v.reminder_times.split(',').map(t=>t.trim()).filter(Boolean);await api(`/api/medicines/${form.dataset.id}`,json('PATCH',v));state.modal=null;await refresh();toast('Medicine plan updated.');return;}
    if(form.id==='language-form'){const language=formData(form).language;await api(`/api/users/${state.user.id}`,json('PATCH',{language}));state.user.language=language;render();toast('Language preference saved.');return;}
    if(form.id==='link-caregiver-form'){await api(`/api/patients/${state.patient.id}/caregivers/${formData(form).caregiver_id}`,{method:'PUT'});await refresh();toast('Caregiver connected.');return;}
    if(form.id==='request-access-form'){const v=formData(form);await api('/api/caregiver-requests',json('POST',v));state.modal=null;await refresh();toast('Access request sent. The patient must approve it.');return;}
    if(form.id==='patient-profile-form'){const v=formData(form);for(const key of Object.keys(v))if(v[key]==='')delete v[key];await api(`/api/patients/${state.patient.id}`,json('PATCH',v));state.modal=null;await refresh();toast('Your patient profile was updated.');return;}
    if(form.id==='appointment-form'){const v=formData(form);if(v.doctor==='')delete v.doctor;if(v.notes==='')delete v.notes;await api(`/api/patients/${state.patient.id}/appointments`,json('POST',v));await refresh();toast('Follow-up added. We’ll remind your care team.');return;}
    if(form.id==='reminder-form'){const v=formData(form);if(!v.body)delete v.body;await api(`/api/patients/${state.patient.id}/reminders`,json('POST',v));await refresh();toast('Reminder added.');return;}
    if(form.id==='contact-form'){await api('/api/contact',json('POST',formData(form)));form.reset();toast('Thanks. Your message has been received.');return;}
    if(form.id==='chat-form'){const message=formData(form).message;const copy=assistantUi[state.user?.language]||assistantUi.en;form.reset();const pending=document.createElement('div');pending.className='chat-bubble chat-bot';pending.textContent=copy.thinking;document.querySelector('#chat-window')?.append(pending);try{const answer=await api('/api/chat',json('POST',{message,patient_id:state.patient?.id||null}));pending.remove();state.chatMessages.push({role:'user',message},{role:'assistant',message:answer.reply});renderChatMessage(message,'user');renderChatMessage(answer.reply,'bot');}catch(e){pending.remove();toast(e.message,true);}return;}
  }catch(e){toast(e.message,true);}
});

function exportReport(){if(!state.report)return;const r=state.report;const lines=[`CareMate report — ${state.patient?.name||''}`,`Period: ${r.period.start} to ${r.period.end}`,`Overall adherence: ${r.overall_adherence_percent??'No data'}%`,`Taken: ${r.total_taken}`,`Missed: ${r.total_missed}`,'','Medicine,Taken,Missed,Adherence %,Days left,Quantity left',...r.medicines.map(m=>[m.medicine_name,m.taken,m.missed,m.adherence_percent??'',m.remaining_days??'',m.remaining_quantity??''].map(x=>`"${String(x).replaceAll('"','""')}"`).join(','))];const blob=new Blob([lines.join('\n')],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`caremate-${(state.patient?.name||'report').toLowerCase().replace(/[^a-z0-9]+/g,'-')}.csv`;a.click();URL.revokeObjectURL(a.href);}

function startPolling(){if(pollTimer)return;pollTimer=setInterval(async()=>{if(state.token){try{await pollNotifications();await loadPatientData();const cutoff=(()=>{const n=new Date();return `${String(n.getHours()).padStart(2,'0')}:${String(n.getMinutes()).padStart(2,'0')}`;})();for(const dose of state.schedule.filter(x=>x.status==='pending'&&x.scheduled_date===localDate()&&x.scheduled_time<=cutoff)){const key=`${dose.medicine_id}:${dose.scheduled_date}:${dose.scheduled_time}`;if(!state.alertedDoseKeys.has(key)){state.alertedDoseKeys.add(key);if('Notification'in window&&Notification.permission==='granted')new Notification('CareMate: time for medicine',{body:`${dose.medicine_name}${dose.dose?` (${dose.dose})`:''} · ${humanTime(dose.scheduled_time)}`});}}const focused=document.activeElement?.matches('input,textarea,select');if(!focused&&!state.modal)render();}catch(e){console.warn(e);}}},25000);}
async function start(){applyTheme();if(!state.token){renderLanding();return;}showLoading();await loadWorkspace();startPolling();}
start();
